import{_ as n,l as r,o as e,c as l,v as t,p as s,x as i,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"回填偏差","description":"","frontmatter":{"title":"回填偏差","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-data-backfill-bias.md","filePath":"quant/alt-data-backfill-bias.md","lastUpdated":1789023840000}'),h={name:"quant/alt-data-backfill-bias.md"};function c(B,a,A,m,u,_){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="回填偏差" tabindex="-1">回填偏差 <a class="header-anchor" href="#回填偏差" aria-label="Permalink to &quot;回填偏差&quot;">​</a></h1><div class="epigraph"><p>另类数据供应商在你买入历史的那天，已经知道哪些公司活到了现在、哪些门店还开着、哪一版算法把云层处理得更好。把这本日历当 $t$ 日可知，是另类数据版的前视。</p><footer>—— 对照 Croushore and Stark 对宏观实时数据集的动机；另类数据中的生存与修订问题见 Katona 等对另类数据进入资本市场的讨论</footer></div><p><a href="/quant/options-as-spot-signal">期权链作为现货信号</a>把一条相对干净、有交易所时钟的另类源用到了现货。本课打开回填：卫星、消费、网页、文本供应商交付「2005 年至今」面板时，往往含有当时并不存在的修订、覆盖与存活。Croushore–Stark 为宏观建立实时数据库，正是因为终值与初值不同。另类数据同样有 vintage。后课面板构造与卫星特征都默认：没有 vintage，就没有可交易的点-in-time。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>回填偏差至少四层。生存：历史只包含今日仍在覆盖名单上的公司或设施，退市、关店、破产被拿掉。覆盖扩张：供应商后来才追踪的名字，被填上「历史」特征，早期截面其实更窄。算法修订：云检测、NLP 模型重跑，过去的特征值被改写。延迟伪装：交付文件的时间戳是研究购买日，不是当时可获得日。四层可以同时存在。用终版面板训练、用终版面板回测，IC 会漂亮，实盘用当时版本会掉一块——掉的是回填，不是拥挤。</p><p>缺口是要求供应商或内部管道提供 <code>as_of</code>：每一观测在何时变为对客户可用。没有这一列，另类数据不能进生产信号，只能当事后解释。</p><h3 id="回填不是幸存者偏差的别名" tabindex="-1">回填不是幸存者偏差的别名 <a class="header-anchor" href="#回填不是幸存者偏差的别名" aria-label="Permalink to &quot;回填不是幸存者偏差的别名&quot;">​</a></h3><p>幸存者偏差通常指股票宇宙。回填还改<strong>特征值本身</strong>。一家一直存活的公司，其 2014 年的卫星营收代理可能在 2020 年被新模型改掉。点-in-time 股票宇宙挡不住这种修订。必须对特征做版本，像宏观实时数据集那样。</p><p><span class="marginnote">试用数据尤其危险：供应商给你的样本往往是覆盖最好、修订最多的名字。容量与拥挤课已经警告选择偏差；回填是同一偏差在数据采购上的版本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合同与工程都要求 vintage 文件：每日交付快照存档，不许在旧快照上覆盖。回测 API 只允许 <code>as_of ≤ 决策时刻</code>。对照实验：终版面板 vs vintage 面板的 IC 差，就是回填贡献。差很大，说明 alpha 来自修订，不是来自当时信息。覆盖矩阵：每个日期哪些名字非缺失；覆盖随时间变宽时，早期横截面不可与后期直接比，应在共同覆盖上检验。</p><p>与公司行为对齐：设施列表必须随分拆、并购更新，且更新不得前移到宣布前。地理映射用当时的门店名单，不是今日官网。</p><h3 id="文本与网页的特殊回填" tabindex="-1">文本与网页的特殊回填 <a class="header-anchor" href="#文本与网页的特殊回填" aria-label="Permalink to &quot;文本与网页的特殊回填&quot;">​</a></h3><p>网页被改、新闻被删、社交账号被封。抓取若只存今日能抓到的 URL，历史情绪是存活文本。必须存当时抓取的原文快照。合规课会限制你能存什么；在允许的范围内，快照是点-in-time 的唯一方法。供应商「历史情绪分数」若不能提供当时分数，视为无 vintage。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>回填把未来信息写入过去特征，等效于前视。生存回填让模型在「将会存活」的条件分布上训练，实盘没有这个条件。算法修订把不可交易的测量改进写成过去的 alpha。市场若在数据发布当时已经部分定价，终版还会把后来才知道的测量误差修掉，进一步美化。Katona 等人讨论另类数据的分配效应时，隐含前提是数据在当时被一部分人持有；回填研究把「当时」弄丢了，分配效应也无法定义。</p><p><span class="marginnote">不要用终版卫星特征去「验证」当时的实现价差或订单流。两边时钟都错，相关没有含义。</span></p>',17)),(e(),s(E,null,{default:i(()=>[p(o,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TB%0A%20%20F%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E7%BB%88%E7%89%88%E9%9D%A2%E6%9D%BF%22%5D%20--%3E%20B1%5B%22%E7%94%9F%E5%AD%98%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20F%20--%3E%20B2%5B%22%E8%A6%86%E7%9B%96%E6%89%A9%E5%BC%A0%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20F%20--%3E%20B3%5B%22%E7%AE%97%E6%B3%95%E4%BF%AE%E8%AE%A2%22%5D%0A%20%20F%20--%3E%20B4%5B%22%E4%BA%A4%E4%BB%98%E6%97%B6%E9%92%9F%E4%BC%AA%E8%A3%85%22%5D%0A%20%20V%5B%22vintage%20%2F%20as_of%20%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20PIT%5B%22%E7%82%B9-in-time%20%E7%89%B9%E5%BE%81%22%5D%0A%20%20PIT%20--%3E%20S%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E4%BF%A1%E5%8F%B7%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="试用样本往往是回填最重的子样本" tabindex="-1">试用样本往往是回填最重的子样本 <a class="header-anchor" href="#试用样本往往是回填最重的子样本" aria-label="Permalink to &quot;试用样本往往是回填最重的子样本&quot;">​</a></h3><p>供应商给你「效果最好」的历史，覆盖与修订都经过选择。应用该样本估 IC，再把覆盖推广到全宇宙，是把回填与选择偏差乘在一起。合同应要求随机或全覆盖 vintage。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>交易所成交回放一般不回填价格（更正另说），这是另类数据与市场数据的差别。宏观实时数据库是榜样，不是所有另类供应商都愿意提供。不能提供则降级为宏观解释变量，不进下单。下一课在有 vintage 的前提下把不规则观测建成面板。</p><p><span class="marginnote">终版卫星计数与当时订单流的相关，两边时钟都可能错。这种相关不能当「另类数据已被定价」的证据。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回填含生存、覆盖、算法修订与交付时钟四层，都会造成前视。</li><li>没有 <code>as_of</code> 的另类历史不能当点-in-time 信号。</li><li>终版与 vintage 的 IC 差度量回填贡献。</li><li>特征修订 ≠ 股票宇宙幸存者，两套都要管。</li><li>试用样本往往是回填最严重的子样本。</li><li>出处：Croushore and Stark, <em>Journal of Econometrics</em>, 2001；另类数据与资本市场见 Katona, Painter, Patatoukas and Zeng 及相关讨论；点-in-time 原则见本课程序研究偏差主干。</li></ul>',7))])}const q=n(h,[["render",c]]);export{b as __pageData,q as default};
